**What this code covers**

- Logs every method call with arguments and return value
- Measures and prints execution time of a method
- Validates that specified positional arguments are positive numbers
- Retries a method on failure
- Decorator 3: Validate Arguments
- Decorator 5: Cache Results
- Apply decorators to a real class
- CLASS-BASED DECORATORS — decorator is a CLASS

**Defines:** `log_method()`, `timer()`, `validate_positive()`, `retry()`, `memoize()`, `MathService`, `RateLimiter`, `Singleton`, `TypeCheck`, `EmailService`

### ✅ Example 1 — Function Decorators on Methods (Core Pattern)

```python name=example1_method_decorators.py
import time
import functools
from datetime import datetime

# ══════════════════════════════════════════════════
#  BUILDING REUSABLE METHOD DECORATORS
# ══════════════════════════════════════════════════

# ─── Decorator 1: Logging ───
def log_method(func):
    """Logs every method call with arguments and return value"""
    @functools.wraps(func)   # preserves func name/docstring!
    def wrapper(self, *args, **kwargs):
        print(f"📋 [{datetime.now().strftime('%H:%M:%S')}] "
              f"CALL  → {self.__class__.__name__}.{func.__name__}"
              f"({args}, {kwargs})")
        result = func(self, *args, **kwargs)
        print(f"📋 [{datetime.now().strftime('%H:%M:%S')}] "
              f"RETURN← {self.__class__.__name__}.{func.__name__}"
              f" = {result!r}")
        return result
    return wrapper

# ─── Decorator 2: Timer ───
def timer(func):
    """Measures and prints execution time of a method"""
    @functools.wraps(func)
    def wrapper(self, *args, **kwargs):
        start  = time.perf_counter()
        result = func(self, *args, **kwargs)
        end    = time.perf_counter()
        print(f"⏱️  {self.__class__.__name__}.{func.__name__} "
              f"took {(end-start)*1000:.3f}ms")
        return result
    return wrapper

# ─── Decorator 3: Validate Arguments ───
def validate_positive(*param_positions):
    """Validates that specified positional arguments are positive numbers"""
    def decorator(func):
        @functools.wraps(func)
        def wrapper(self, *args, **kwargs):
            for pos in param_positions:
                if pos < len(args) and args[pos] <= 0:
                    raise ValueError(
                        f"❌ {func.__name__}: argument at position {pos} "
                        f"must be positive. Got: {args[pos]}"
                    )
            return func(self, *args, **kwargs)
        return wrapper
    return decorator

# ─── Decorator 4: Retry ───
def retry(max_attempts=3, delay=0.1, exceptions=(Exception,)):
    """Retries a method on failure"""
    def decorator(func):
        @functools.wraps(func)
        def wrapper(self, *args, **kwargs):
            last_error = None
            for attempt in range(1, max_attempts + 1):
                try:
                    return func(self, *args, **kwargs)
                except exceptions as e:
                    last_error = e
                    if attempt < max_attempts:
                        print(f"⚠️  Attempt {attempt}/{max_attempts} failed: {e}. "
                              f"Retrying in {delay}s...")
                        time.sleep(delay)
            raise last_error
        return wrapper
    return decorator

# ─── Decorator 5: Cache Results ───
def memoize(func):
    """Caches method results based on arguments"""
    cache = {}
    @functools.wraps(func)
    def wrapper(self, *args):
        if args not in cache:
            print(f"  💾 Cache MISS for {func.__name__}{args} — computing...")
            cache[args] = func(self, *args)
        else:
            print(f"  ⚡ Cache HIT  for {func.__name__}{args}")
        return cache[args]
    return wrapper

# ─── Apply decorators to a real class ───
class MathService:
    """Service demonstrating various method decorators"""

    @log_method
    @timer
    def add(self, a, b):
        """Add two numbers"""
        return a + b

    @validate_positive(0, 1)
    def divide(self, a, b):
        """Divide with validation"""
        return a / b

    @memoize
    def fibonacci(self, n):
        """Fibonacci — slow without memoization!"""
        if n <= 1:
            return n
        return self.fibonacci(n - 1) + self.fibonacci(n - 2)

    @retry(max_attempts=3, delay=0.05, exceptions=(ConnectionError,))
    def fetch_data(self, url):
        """Simulates a flaky network call"""
        import random
        if random.random() < 0.7:   # 70% failure rate for demo
            raise ConnectionError("Network timeout!")
        return f"Data from {url}"

# ─── Testing ───
svc = MathService()

print("=== log_method + timer ===")
result = svc.add(10, 20)

print("\n=== validate_positive ===")
print(svc.divide(100, 4))
try:
    svc.divide(-5, 2)    # invalid!
except ValueError as e:
    print(e)

print("\n=== memoize ===")
svc.fibonacci(10)   # computed
svc.fibonacci(10)   # from cache!
svc.fibonacci(8)    # from cache — sub-results were cached too!

print("\n=== retry ===")
import random
random.seed(99)
try:
    result = svc.fetch_data("https://api.example.com/data")
    print(f"Got: {result}")
except ConnectionError as e:
    print(f"All attempts failed: {e}")
```

### ✅ Example 2 — Class-Based Decorators (Using `__call__`)

```python name=example2_class_based_decorators.py
import functools
import time
from collections import defaultdict

# ══════════════════════════════════════════════════
#  CLASS-BASED DECORATORS — decorator is a CLASS
#  with __init__ (stores config) and __call__ (wraps)
# ══════════════════════════════════════════════════

class RateLimiter:
    """
    Class-based decorator: limits how many times a method
    can be called per minute. Like an API rate limiter.
    """

    def __init__(self, max_calls: int, period_seconds: float = 60.0):
        self.max_calls     = max_calls
        self.period        = period_seconds
        self.calls         = defaultdict(list)  # key → list of timestamps

    def __call__(self, func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            now  = time.time()
            key  = f"{func.__name__}"

            # Remove calls outside the window
            self.calls[key] = [
                t for t in self.calls[key]
                if now - t < self.period
            ]

            if len(self.calls[key]) >= self.max_calls:
                wait = self.period - (now - self.calls[key][0])
                raise RuntimeError(
                    f"🚫 Rate limit exceeded for '{key}'. "
                    f"Max {self.max_calls} calls per {self.period}s. "
                    f"Try again in {wait:.1f}s"
                )

            self.calls[key].append(now)
            print(f"  ✅ Call {len(self.calls[key])}/{self.max_calls} allowed")
            return func(*args, **kwargs)
        return wrapper

class Singleton:
    """
    Class decorator that enforces Singleton pattern —
    only ONE instance of the decorated class can exist.
    """

    def __init__(self, cls):
        self._cls      = cls
        self._instance = None
        functools.update_wrapper(self, cls)

    def __call__(self, *args, **kwargs):
        if self._instance is None:
            print(f"  🆕 Creating {self._cls.__name__} instance (first time)")
            self._instance = self._cls(*args, **kwargs)
        else:
            print(f"  ♻️  Returning existing {self._cls.__name__} instance")
        return self._instance

class TypeCheck:
    """
    Class decorator that adds runtime type checking
    to all method arguments based on type hints.
    """

    def __init__(self, cls):
        self._cls = cls
        self._wrap_methods()
        functools.update_wrapper(self, cls)

    def _wrap_methods(self):
        import inspect
        for name, method in inspect.getmembers(self._cls, predicate=inspect.isfunction):
            if not name.startswith('_'):
                hints = method.__annotations__
                if hints:
                    setattr(self._cls, name, self._type_checked(method, hints))

    def _type_checked(self, func, hints):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            import inspect
            sig    = inspect.signature(func)
            params = list(sig.parameters.keys())
            for i, (arg, param_name) in enumerate(zip(args[1:], params[1:]), 1):
                if param_name in hints:
                    expected = hints[param_name]
                    if not isinstance(arg, expected):
                        raise TypeError(
                            f"❌ {func.__name__}: '{param_name}' expected "
                            f"{expected.__name__}, got {type(arg).__name__}"
                        )
            return func(*args, **kwargs)
        return wrapper

    def __call__(self, *args, **kwargs):
        return self._cls(*args, **kwargs)

# ─── Apply class-based decorators ───

# 1. RateLimiter as method decorator
rate_limit = RateLimiter(max_calls=3, period_seconds=5)

class EmailService:
    @rate_limit
    def send_email(self, to, subject):
        print(f"  📧 Email sent to {to}: {subject}")
        return True

print("=== RateLimiter ===")
svc = EmailService()
svc.send_email("alice@test.com", "Welcome!")
svc.send_email("bob@test.com",   "Invoice")
svc.send_email("carol@test.com", "Newsletter")
try:
    svc.send_email("dave@test.com", "Promo")   # 4th call — limit hit!
except RuntimeError as e:
    print(f"\n{e}")

# 2. Singleton as class decorator
@Singleton
class DatabasePool:
    def __init__(self, max_connections=10):
        self.max_connections = max_connections
        self.active          = 0
        print(f"  🔧 Pool initialized (max={max_connections})")

    def get_connection(self):
        self.active += 1
        return f"conn_{self.active}"

print("\n=== Singleton ===")
pool1 = DatabasePool(10)
pool2 = DatabasePool(20)   # returns SAME instance!
pool3 = DatabasePool()

print(f"pool1 is pool2: {pool1 is pool2}")  # True!
print(f"pool1 is pool3: {pool1 is pool3}")  # True!
print(f"Max connections: {pool1.max_connections}")  # 10 (first init)

# 3. TypeCheck as class decorator
@TypeCheck
class Calculator:
    def add(self, a: int, b: int) -> int:
        return a + b

    def multiply(self, a: float, b: float) -> float:
        return a * b

print("\n=== TypeCheck ===")
calc = Calculator()
print(calc.add(5, 3))          # ✅ 8
print(calc.multiply(2.5, 4.0)) # ✅ 10.0
try:
    calc.add("5", 3)           # ❌ TypeError!
except TypeError as e:
    print(e)
```

### ✅ Example 3 — Decorators with Arguments (Decorator Factories)

```python name=example3_decorator_factories.py
import functools
import time
import logging

logging.basicConfig(level=logging.INFO,
                    format='%(asctime)s - %(levelname)s - %(message)s')

# ══════════════════════════════════════════════════
#  DECORATOR FACTORIES — decorators that accept arguments
#  @decorator(arg1, arg2) — 3-level nesting
# ══════════════════════════════════════════════════

# ─── Factory 1: Access Control ───
def require_role(*allowed_roles):
    """
    @require_role('admin', 'manager')
    def delete_user(...): ...
    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(self, *args, **kwargs):
            user_role = getattr(self, 'current_user_role', None)
            if user_role not in allowed_roles:
                raise PermissionError(
                    f"🚫 Access denied! '{func.__name__}' requires "
                    f"role: {allowed_roles}. Current role: '{user_role}'"
                )
            print(f"  🔓 Access granted for role '{user_role}'")
            return func(self, *args, **kwargs)
        return wrapper
    return decorator

# ─── Factory 2: Timeout ───
def timeout(seconds):
    """
    @timeout(5)   — raises TimeoutError if method takes > 5 seconds
    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(self, *args, **kwargs):
            import threading
            result    = [None]
            exception = [None]

            def target():
                try:
                    result[0] = func(self, *args, **kwargs)
                except Exception as e:
                    exception[0] = e

            thread = threading.Thread(target=target)
            thread.daemon = True
            thread.start()
            thread.join(timeout=seconds)

            if thread.is_alive():
                raise TimeoutError(
                    f"⏰ {func.__name__} exceeded {seconds}s timeout!"
                )
            if exception[0]:
                raise exception[0]
            return result[0]
        return wrapper
    return decorator

# ─── Factory 3: Deprecated Warning ───
def deprecated(reason="", replacement=None):
    """
    @deprecated(reason="Use new_method instead", replacement="new_method")
    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            import warnings
            msg = f"⚠️  DEPRECATED: '{func.__name__}'"
            if reason:      msg += f" — {reason}"
            if replacement: msg += f" → Use '{replacement}' instead"
            warnings.warn(msg, DeprecationWarning, stacklevel=2)
            print(f"  {msg}")
            return func(*args, **kwargs)
        return wrapper
    return decorator

# ─── Factory 4: Retry with Exponential Backoff ───
def retry_with_backoff(max_attempts=3, base_delay=1.0,
                       backoff_factor=2.0, exceptions=(Exception,)):
    """
    @retry_with_backoff(max_attempts=5, base_delay=0.5, backoff_factor=2)
    Retries with exponentially increasing delays: 0.5s, 1s, 2s, 4s...
    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(self, *args, **kwargs):
            delay = base_delay
            for attempt in range(1, max_attempts + 1):
                try:
                    return func(self, *args, **kwargs)
                except exceptions as e:
                    if attempt == max_attempts:
                        raise
                    print(f"  ⚠️  Attempt {attempt} failed: {e}. "
                          f"Waiting {delay:.1f}s (backoff)...")
                    time.sleep(min(delay, 0.1))   # cap for demo
                    delay *= backoff_factor
        return wrapper
    return decorator

# ─── Factory 5: Audit Log ───
def audit_log(action):
    """
    @audit_log("DELETE_USER")
    Records who did what and when for compliance.
    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(self, *args, **kwargs):
            user   = getattr(self, 'current_user', 'UNKNOWN')
            logger = logging.getLogger('AUDIT')
            logger.info(
                f"ACTION={action} | USER={user} | "
                f"METHOD={func.__name__} | ARGS={args}"
            )
            result = func(self, *args, **kwargs)
            logger.info(f"ACTION={action} | STATUS=SUCCESS | RESULT={result!r}")
            return result
        return wrapper
    return decorator

# ─── Real class using multiple factory decorators ───
class AdminPanel:

    def __init__(self, current_user, current_user_role):
        self.current_user      = current_user
        self.current_user_role = current_user_role

    @require_role('admin')
    @audit_log("DELETE_USER")
    def delete_user(self, user_id):
        print(f"  🗑️  Deleting user {user_id}...")
        return f"user_{user_id}_deleted"

    @require_role('admin', 'manager')
    @audit_log("VIEW_REPORT")
    def view_report(self, report_id):
        print(f"  📊 Loading report {report_id}...")
        return f"report_data_{report_id}"

    @deprecated(reason="Use export_csv instead", replacement="export_csv")
    def export_excel(self, data):
        print(f"  📊 Exporting to Excel...")
        return "excel_data"

    def export_csv(self, data):
        print(f"  📊 Exporting to CSV...")
        return "csv_data"

    @retry_with_backoff(max_attempts=3, base_delay=0.05, exceptions=(IOError,))
    def backup_database(self):
        import random
        if random.random() < 0.6:
            raise IOError("DB connection interrupted")
        return "backup_complete"

# ─── Testing ───
print("=== require_role + audit_log ===")
admin   = AdminPanel("alice", "admin")
manager = AdminPanel("bob",   "manager")
viewer  = AdminPanel("carol", "viewer")

admin.delete_user(42)

print()
manager.view_report("Q4-2025")

print()
try:
    viewer.delete_user(42)   # ❌ no permission
except PermissionError as e:
    print(e)

print("\n=== deprecated ===")
admin.export_excel({"data": [1, 2, 3]})

print("\n=== retry_with_backoff ===")
import random
random.seed(5)
try:
    result = admin.backup_database()
    print(f"  ✅ {result}")
except IOError as e:
    print(f"  ❌ All attempts failed: {e}")
```

### ✅ Example 4 — Stacked Decorators & Real-World Patterns

```python name=example4_stacked_real_world.py
import functools
import time
import json
from datetime import datetime

# ══════════════════════════════════════════════════
#  STACKED DECORATORS + REAL PRODUCTION PATTERNS
# ══════════════════════════════════════════════════

# ─── Building the decorator toolkit ───
def log(func):
    @functools.wraps(func)
    def wrapper(self, *args, **kwargs):
        print(f"[LOG] {func.__name__} called")
        return func(self, *args, **kwargs)
    return wrapper

def timer(func):
    @functools.wraps(func)
    def wrapper(self, *args, **kwargs):
        s = time.perf_counter()
        r = func(self, *args, **kwargs)
        print(f"[TIME] {func.__name__}: {(time.perf_counter()-s)*1000:.2f}ms")
        return r
    return wrapper

def validate_input(func):
    @functools.wraps(func)
    def wrapper(self, *args, **kwargs):
        for arg in args:
            if arg is None:
                raise ValueError(f"❌ {func.__name__}: None argument not allowed")
        return func(self, *args, **kwargs)
    return wrapper

def cache_result(ttl_seconds=60):
    """Cache with TTL (Time To Live)"""
    def decorator(func):
        _cache = {}  # {args: (result, timestamp)}
        @functools.wraps(func)
        def wrapper(self, *args):
            now = time.time()
            if args in _cache:
                result, ts = _cache[args]
                if now - ts < ttl_seconds:
                    print(f"  ⚡ Cache hit: {func.__name__}{args}")
                    return result
            result      = func(self, *args)
            _cache[args] = (result, now)
            print(f"  💾 Cached: {func.__name__}{args}")
            return result
        wrapper.clear_cache = lambda: _cache.clear()
        return wrapper
    return decorator

# ─── STACKED DECORATORS ───
# Applied BOTTOM-UP: validate_input first, then timer, then log
class DataService:
    """
    Demonstrates stacked decorators.
    Execution order: outermost decorator wraps first, runs first.
    @log          → runs 1st (outermost)
    @timer        → runs 2nd
    @validate_input → runs 3rd (innermost, closest to function)
    """

    @log
    @timer
    @validate_input
    def process_data(self, data, transform):
        """Process data with a transform function"""
        time.sleep(0.01)   # simulate work
        return transform(data)

    @cache_result(ttl_seconds=30)
    def get_user(self, user_id):
        """Expensive DB call — cached for 30 seconds"""
        print(f"  🔍 DB Query for user {user_id}...")
        time.sleep(0.05)
        return {"id": user_id, "name": f"User_{user_id}", "active": True}

    @log
    @cache_result(ttl_seconds=10)
    def get_settings(self, key):
        print(f"  🔍 Loading setting '{key}'...")
        return {"theme": "dark", "lang": "en"}.get(key, "default")

# ─── Testing Stacked ───
print("=== Stacked Decorators ===")
svc = DataService()
svc.process_data([1, 2, 3, 4, 5], sum)

print("\n=== Cache TTL ===")
svc.get_user(42)   # DB query
svc.get_user(42)   # from cache
svc.get_user(99)   # different user → DB query
svc.get_user(42)   # still in cache

print("\n=== validate_input ===")
try:
    svc.process_data(None, sum)
except ValueError as e:
    print(e)

# ─── REAL PATTERN: Django-style @login_required ───
class Request:
    def __init__(self, user=None, method="GET", data=None):
        self.user   = user
        self.method = method
        self.data   = data or {}

class User:
    def __init__(self, username, is_authenticated, role="user"):
        self.username         = username
        self.is_authenticated = is_authenticated
        self.role             = role

def login_required(func):
    """Django-style: redirects to login if not authenticated"""
    @functools.wraps(func)
    def wrapper(self, request, *args, **kwargs):
        if not request.user or not request.user.is_authenticated:
            return {"error": "Login required", "redirect": "/login/"}
        return func(self, request, *args, **kwargs)
    return wrapper

def permission_required(permission):
    """Django-style: checks user has specific permission"""
    def decorator(func):
        @functools.wraps(func)
        def wrapper(self, request, *args, **kwargs):
            user_role = getattr(request.user, 'role', 'anonymous')
            perms     = {
                "view_reports"   : ["admin", "manager", "analyst"],
                "delete_records" : ["admin"],
                "edit_settings"  : ["admin", "manager"],
            }
            allowed = perms.get(permission, [])
            if user_role not in allowed:
                return {
                    "error": f"Permission '{permission}' required",
                    "your_role": user_role
                }
            return func(self, request, *args, **kwargs)
        return wrapper
    return decorator

def rate_limit_view(max_per_minute=60):
    """API rate limiting for views"""
    calls = {}
    def decorator(func):
        @functools.wraps(func)
        def wrapper(self, request, *args, **kwargs):
            user_key = getattr(request.user, 'username', 'anon')
            now      = time.time()
            calls[user_key] = [
                t for t in calls.get(user_key, [])
                if now - t < 60
            ]
            if len(calls.get(user_key, [])) >= max_per_minute:
                return {"error": "Rate limit exceeded", "retry_after": 60}
            calls.setdefault(user_key, []).append(now)
            return func(self, request, *args, **kwargs)
        return wrapper
    return decorator

# ─── Views using stacked real-world decorators ───
class ReportView:

    @login_required
    @permission_required("view_reports")
    @rate_limit_view(max_per_minute=10)
    def get(self, request, report_id):
        return {"report": f"data_for_{report_id}", "generated_by": request.user.username}

    @login_required
    @permission_required("delete_records")
    def delete(self, request, record_id):
        return {"deleted": record_id, "by": request.user.username}

print("\n=== Django-style View Decorators ===")
view = ReportView()

# Anonymous user
anon_req  = Request(user=None)
print(view.get(anon_req, "Q4-2025"))   # login required

# Authenticated but wrong role
viewer    = User("carol", True, "viewer")
view_req  = Request(user=viewer)
print(view.get(view_req, "Q4-2025"))   # permission denied

# Correct role
analyst   = User("alice", True, "analyst")
good_req  = Request(user=analyst)
print(view.get(good_req, "Q4-2025"))   # ✅ success

# Admin delete
admin     = User("bob", True, "admin")
admin_req = Request(user=admin)
print(view.delete(admin_req, 42))      # ✅ success

# Non-admin delete attempt
print(view.delete(good_req, 42))       # permission denied
```

### ✅ Example 5 — Class Decorators for Cross-Cutting Concerns

```python name=example5_class_decorators.py
import functools
import time
import copy

# ══════════════════════════════════════════════════
#  CLASS DECORATORS — decorate the ENTIRE CLASS
# ══════════════════════════════════════════════════

# ─── Class Decorator 1: Auto-add __repr__ ───
def auto_repr(cls):
    """
    Automatically generates __repr__ from __init__ parameters.
    No more writing __repr__ manually!
    """
    import inspect
    params = list(inspect.signature(cls.__init__).parameters.keys())[1:]  # skip self

    def __repr__(self):
        attrs = ', '.join(
            f"{p}={getattr(self, p, getattr(self, f'_{p}', '?'))!r}"
            for p in params
        )
        return f"{cls.__name__}({attrs})"

    cls.__repr__ = __repr__
    return cls

# ─── Class Decorator 2: Freeze class after init ───
def frozen(cls):
    """
    Makes all instances immutable after __init__ completes.
    Raises AttributeError on any assignment after creation.
    """
    original_init = cls.__init__

    def new_init(self, *args, **kwargs):
        object.__setattr__(self, '_frozen', False)
        original_init(self, *args, **kwargs)
        object.__setattr__(self, '_frozen', True)

    def __setattr__(self, name, value):
        if object.__getattribute__(self, '_frozen'):
            raise AttributeError(
                f"❌ {cls.__name__} is immutable! "
                f"Cannot set '{name}'"
            )
        object.__setattr__(self, name, value)

    cls.__init__    = new_init
    cls.__setattr__ = __setattr__
    return cls

# ─── Class Decorator 3: Add benchmarking to ALL methods ───
def benchmark_all(cls):
    """
    Wraps ALL public methods of a class to measure their execution time.
    """
    for name, method in list(vars(cls).items()):
        if callable(method) and not name.startswith('_'):
            @functools.wraps(method)
            def timed(self, *args, _method=method, _name=name, **kwargs):
                start  = time.perf_counter()
                result = _method(self, *args, **kwargs)
                elapsed = (time.perf_counter() - start) * 1000
                print(f"  ⏱️  {cls.__name__}.{_name}: {elapsed:.3f}ms")
                return result
            setattr(cls, name, timed)
    return cls

# ─── Class Decorator 4: Observable (Event System) ───
def observable(cls):
    """
    Adds event subscription/publishing to any class.
    obj.on('event_name', callback)
    obj.emit('event_name', data)
    """
    original_init = cls.__init__

    def new_init(self, *args, **kwargs):
        object.__setattr__(self, '_listeners', {})
        original_init(self, *args, **kwargs)

    def on(self, event, callback):
        listeners = object.__getattribute__(self, '_listeners')
        listeners.setdefault(event, []).append(callback)
        print(f"  📡 Subscribed to '{event}'")

    def off(self, event, callback):
        listeners = object.__getattribute__(self, '_listeners')
        if event in listeners:
            listeners[event].remove(callback)

    def emit(self, event, *args, **kwargs):
        listeners = object.__getattribute__(self, '_listeners')
        for cb in listeners.get(event, []):
            cb(*args, **kwargs)

    cls.__init__ = new_init
    cls.on       = on
    cls.off      = off
    cls.emit     = emit
    return cls

# ─── Apply class decorators ───

@auto_repr
class Point:
    def __init__(self, x, y, z=0):
        self.x = x
        self.y = y
        self.z = z

    def distance_from_origin(self):
        return (self.x**2 + self.y**2 + self.z**2) ** 0.5

@frozen
@auto_repr
class Money:
    def __init__(self, amount, currency):
        self.amount   = float(amount)
        self.currency = currency

    def convert(self, rate):
        return Money(self.amount * rate, self.currency)

@benchmark_all
class DataProcessor:
    def process(self, data):
        time.sleep(0.01)
        return [x * 2 for x in data]

    def filter_evens(self, data):
        return [x for x in data if x % 2 == 0]

    def summarize(self, data):
        time.sleep(0.005)
        return {"sum": sum(data), "avg": sum(data)/len(data), "count": len(data)}

@observable
class ShoppingCart:
    def __init__(self):
        self.items = []
        self.total = 0.0

    def add_item(self, name, price):
        self.items.append({"name": name, "price": price})
        self.total += price
        self.emit("item_added", name=name, price=price, total=self.total)

    def checkout(self):
        self.emit("checkout", items=self.items, total=self.total)
        self.items = []
        self.total = 0.0

